19	/**
20	 * Reassembles incremental A2A streaming updates into a coherent result.
21	 * Shows sequential status/messages followed by all reassembled artifacts.
22	 */
23	export class A2AResultReassembler {
24	  private messageLog: string[] = [];
25	  private artifacts = new Map<string, Artifact>();
26	  private artifactChunks = new Map<string, string[]>();
27	
28	  /**
29	   * Processes a new chunk from the A2A stream.
30	   */
31	  update(chunk: SendMessageResult) {
32	    if (!('kind' in chunk)) return;
33	
34	    switch (chunk.kind) {
35	      case 'status-update':
36	        this.pushMessage(chunk.status?.message);
37	        break;
38	
39	      case 'artifact-update':
40	        if (chunk.artifact) {
41	          const id = chunk.artifact.artifactId;
42	          const existing = this.artifacts.get(id);
43	
44	          if (chunk.append && existing) {
45	            for (const part of chunk.artifact.parts) {
46	              existing.parts.push(structuredClone(part));
47	            }
48	          } else {
49	            this.artifacts.set(id, structuredClone(chunk.artifact));
50	          }
51	
52	          const newText = extractPartsText(chunk.artifact.parts, '');
53	          let chunks = this.artifactChunks.get(id);
54	          if (!chunks) {
55	            chunks = [];
56	            this.artifactChunks.set(id, chunks);
57	          }
58	          if (chunk.append) {
59	            chunks.push(newText);
60	          } else {
61	            chunks.length = 0;
62	            chunks.push(newText);
63	          }
64	        }
65	        break;
66	
67	      case 'task':
68	        this.pushMessage(chunk.status?.message);
69	        if (chunk.artifacts) {
70	          for (const art of chunk.artifacts) {
71	            this.artifacts.set(art.artifactId, structuredClone(art));
72	            this.artifactChunks.set(art.artifactId, [
73	              extractPartsText(art.parts, ''),
74	            ]);
75	          }
76	        }
77	        break;
78	
79	      case 'message': {
80	        this.pushMessage(chunk);
81	        break;
82	      }
83	
84	      default:
85	        break;
86	    }
87	  }
88	
89	  private pushMessage(message: Message | undefined) {
90	    if (!message) return;
91	    const text = extractPartsText(message.parts, '\n');
92	    if (text && this.messageLog[this.messageLog.length - 1] !== text) {
93	      this.messageLog.push(text);
94	    }
95	  }
96	
97	  /**
98	   * Returns a human-readable string representation of the current reassembled state.
99	   */
100	  toString(): string {
101	    const joinedMessages = this.messageLog.join('\n\n');
102	
103	    const artifactsOutput = Array.from(this.artifacts.keys())
104	      .map((id) => {
105	        const chunks = this.artifactChunks.get(id);
106	        const artifact = this.artifacts.get(id);
107	        if (!chunks || !artifact) return '';
108	        const content = chunks.join('');
109	        const header = artifact.name
110	          ? `Artifact (${artifact.name}):`
111	          : 'Artifact:';
112	        return `${header}\n${content}`;
113	      })
114	      .filter(Boolean)
115	      .join('\n\n');
116	
117	    if (joinedMessages && artifactsOutput) {
118	      return `${joinedMessages}\n\n${artifactsOutput}`;
119	    }
120	    return joinedMessages || artifactsOutput;
121	  }
122	}
123	
124	/**
125	 * Extracts a human-readable text representation from a Message object.
126	 * Handles Text, Data (JSON), and File parts.
127	 */
128	export function extractMessageText(message: Message | undefined): string {
129	  if (!message) {
130	    return '';
131	  }
132	
133	  return extractPartsText(message.parts, '\n');
134	}
135	
136	/**
137	 * Extracts text from an array of parts, joining them with the specified separator.
138	 */
139	function extractPartsText(
140	  parts: Part[] | undefined,
141	  separator: string,
142	): string {
143	  if (!parts || parts.length === 0) {
144	    return '';
145	  }
146	  return parts
147	    .map((p) => extractPartText(p))
148	    .filter(Boolean)
149	    .join(separator);
150	}
151	
152	/**
153	 * Extracts text from a single Part.
154	 */
155	function extractPartText(part: Part): string {
156	  if (isTextPart(part)) {
157	    return part.text;
158	  }
159	
160	  if (isDataPart(part)) {
161	    // Attempt to format known data types if metadata exists, otherwise JSON stringify
162	    return `Data: ${JSON.stringify(part.data)}`;
163	  }
164	
165	  if (isFilePart(part)) {
166	    const fileData = part.file;
167	    if (fileData.name) {
168	      return `File: ${fileData.name}`;
169	    }
170	    if ('uri' in fileData && fileData.uri) {
171	      return `File: ${fileData.uri}`;
172	    }
173	    return `File: [binary/unnamed]`;
174	  }
175	
176	  return '';
177	}
178	
179	// Type Guards
180	
181	function isTextPart(part: Part): part is TextPart {
182	  return part.kind === 'text';
183	}
184	
185	function isDataPart(part: Part): part is DataPart {
186	  return part.kind === 'data';
187	}
188	
189	function isFilePart(part: Part): part is FilePart {
190	  return part.kind === 'file';
191	}
192	
193	function isStatusUpdateEvent(
194	  result: SendMessageResult,
195	): result is TaskStatusUpdateEvent {
196	  return result.kind === 'status-update';
197	}
198	
199	/**
200	 * Returns true if the given state is a terminal state for a task.
201	 */
202	export function isTerminalState(state: TaskState | undefined): boolean {
203	  return (
204	    state === 'completed' ||
205	    state === 'failed' ||
206	    state === 'canceled' ||
207	    state === 'rejected'
208	  );
209	}
210	
211	/**
212	 * Extracts contextId and taskId from a Message, Task, or Update response.
213	 * Follows the pattern from the A2A CLI sample to maintain conversational continuity.
214	 */
215	export function extractIdsFromResponse(result: SendMessageResult): {
216	  contextId?: string;
217	  taskId?: string;
218	  clearTaskId?: boolean;
219	} {
220	  let contextId: string | undefined;
221	  let taskId: string | undefined;
222	  let clearTaskId = false;
223	
224	  if ('kind' in result) {
225	    const kind = result.kind;
226	    if (kind === 'message' || kind === 'artifact-update') {
227	      taskId = result.taskId;
228	      contextId = result.contextId;
229	    } else if (kind === 'task') {
230	      taskId = result.id;
231	      contextId = result.contextId;
232	      if (isTerminalState(result.status?.state)) {
233	        clearTaskId = true;
234	      }
235	    } else if (isStatusUpdateEvent(result)) {
236	      taskId = result.taskId;
237	      contextId = result.contextId;
238	      // Note: We ignore the 'final' flag here per A2A protocol best practices,
239	      // as a stream can close while a task is still in a 'working' state.
240	      if (isTerminalState(result.status?.state)) {
241	        clearTaskId = true;
242	      }
243	    }
244	  }
245	
246	  return { contextId, taskId, clearTaskId };
247	}
