209	   * @param agentName The name of the agent.
210	   * @param taskId The ID of the task to cancel.
211	   * @returns The cancellation response.
212	   */
213	  async cancelTask(agentName: string, taskId: string): Promise<Task> {
214	    const client = this.clients.get(agentName);
215	    if (!client) {
216	      throw new Error(`Agent '${agentName}' not found.`);
217	    }
