+    vi.mocked(DefaultAgentCardResolver.prototype.resolve).mockResolvedValue({
+      ...mockAgentCard,
+      url: 'http://test.agent/real/endpoint',
+    } as AgentCard);
+
+    vi.mocked(ClientFactoryOptions.createFrom).mockImplementation(
