+        messageId: 'a',
+        parts: [],
+        role: 'agent',
+      } as SendMessageResult);
+
+      const expectedContextId = 'user-context-id';
+      const expectedTaskId = 'user-task-id';
+
+      await manager.sendMessage('TestAgent', 'Hello', {
